import { DurableObject } from "cloudflare:workers";
// @ts-expect-error generated by `opennextjs-cloudflare build`
import nextWorker from "../.open-next/worker.js";
// @ts-expect-error generated by scripts/cf-gen-seed.mjs
import seed from "./seed.generated.json";

type SeedTable = { name: string; columns: string[]; rows: unknown[][] };
type Seed = { schema: string[]; tables: SeedTable[] };
type Env = { CAMPUS_APP: DurableObjectNamespace; DB_INSTANCE?: string };

/** First boot of an instance: create the schema and load the demo data. */
function seedIfEmpty(storage: DurableObjectStorage) {
  const found = storage.sql.exec("SELECT count(*) AS n FROM sqlite_master WHERE name = 'users'").one();
  if (found.n) return;
  const { schema, tables } = seed as Seed;
  storage.transactionSync(() => {
    storage.sql.exec("PRAGMA defer_foreign_keys = ON");
    for (const statement of schema) storage.sql.exec(statement);
    for (const { name, columns, rows } of tables) {
      const list = columns.map((c) => `"${c}"`).join(",");
      const marks = columns.map(() => "?").join(",");
      for (const row of rows) storage.sql.exec(`INSERT INTO "${name}" (${list}) VALUES (${marks})`, ...(row as string[]));
    }
  });
}

/** Runs the whole Next app next to its SQLite storage, because the app's DB calls are synchronous. */
export class CampusApp extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => seedIfEmpty(ctx.storage));
    (globalThis as unknown as { __campusDoStorage: DurableObjectStorage }).__campusDoStorage = ctx.storage;
  }

  fetch(request: Request) {
    return nextWorker.fetch(request, this.env, this.ctx);
  }
}

export default {
  // Static files never get here: the assets binding serves them first.
  fetch(request: Request, env: Env) {
    const url = new URL(request.url);
    if (url.pathname === "/") return Response.redirect(`${url.origin}/campus-ai/login`, 302);
    return env.CAMPUS_APP.get(env.CAMPUS_APP.idFromName(env.DB_INSTANCE ?? "v2")).fetch(request);
  },
};
